assert parse_env("A=a#b") == {"A": "a#b"}
assert parse_env("export FOO=bar") == {"FOO": "bar"}
assert parse_env("A=1\nA=2") == {"A": "2"}
assert parse_env("A=") == {"A": ""}
assert parse_env('A="  padded  "') == {"A": "  padded  "}
assert parse_env("URL=https://x/y?a=b") == {"URL": "https://x/y?a=b"}

def must_raise(src, msg):
    try:
        parse_env(src)
    except ValueError as e:
        assert str(e) == msg, repr(str(e))
    else:
        raise AssertionError("no error for " + repr(src))

must_raise("A=1\nnope\n", "invalid line 2: nope")
must_raise("1BAD=x", "invalid line 1: 1BAD=x")
must_raise("=x", "invalid line 1: =x")
